import{_ as t,o as i,c as a,a2 as n}from"./chunks/framework.iWwp2X7T.js";const u=JSON.parse('{"title":"iPhone USB","description":"Mobile Inspector development documentation · iPhone USB","frontmatter":{"title":"iPhone USB","description":"Mobile Inspector development documentation · iPhone USB"},"headers":[],"relativePath":"en/guide/connection-usb.md","filePath":"en/guide/connection-usb.md"}'),o={name:"en/guide/connection-usb.md"};function r(s,e,c,l,p,d){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="iphone-usb" tabindex="-1">iPhone USB <a class="header-anchor" href="#iphone-usb" aria-label="Permalink to &quot;iPhone USB&quot;">​</a></h1><p>USB is the existing wired iPhone flow on a Mac with Xcode/CoreDevice support. It does not require shared Wi-Fi. It is not a generic Android, HarmonyOS or browser USB transport.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Use a physical connected iPhone that trusts the Mac, a working data cable, Xcode command-line tools and OpenSSL. The internal app must already integrate the native SDK and its diagnostic local-network usage declaration. Device signing/install and actual permission prompts remain the app maintainer&#39;s responsibility.</p><h2 id="pair-explicitly" tabindex="-1">Pair explicitly <a class="header-anchor" href="#pair-explicitly" aria-label="Permalink to &quot;Pair explicitly&quot;">​</a></h2><p>In the viewer choose <strong>USB</strong>, select the connected phone, then generate pairing. The server revalidates the physical wired binding and resolves its route; it does not accept an arbitrary client-supplied USB endpoint. USB has no LAN QR.</p><p>Choose <strong>Copy to phone</strong>, paste into the diagnostic panel and connect. Copy uses the selected device&#39;s Xcode pasteboard command only after that click; it does not read the phone clipboard or synchronize automatically. Keep recording stopped during configuration, then start it separately.</p><h2 id="verify-receipt" tabindex="-1">Verify receipt <a class="header-anchor" href="#verify-receipt" aria-label="Permalink to &quot;Verify receipt&quot;">​</a></h2><p>Trigger one harmless internal test action. Confirm its actual event reaches the viewer and matches the intended session. Device discovery, a successful clipboard action or a configured panel alone cannot establish transport receipt.</p><p>If the wire disconnects, stop and reselect the valid device; do not infer identity from a stale selector. Diagnose trust/cable/Xcode prerequisites before changing network settings. <a href="./connection-lan">LAN/manual pairing</a> remains a separate fallback.</p>',10)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
